constexpr uint64_t features=CEPH_FEATURE_PGID64|CEPH_FEATURE_MDSENC|CEPH_FEATURE_MSG_ADDR2|CEPH_FEATUREMASK_SERVER_NAUTILUS;
void write_segment(const std::filesystem::path& path,const ceph::buffer::list& segment){
 const auto bytes=segment.to_str();std::ofstream out(path,std::ios::binary);out.exceptions(std::ios::failbit|std::ios::badbit);out.write(bytes.data(),bytes.size());
}
std::string hex(const std::string& bytes){
 constexpr char digits[]="0123456789abcdef";std::string out;for(unsigned char b:bytes){out+=digits[b>>4];out+=digits[b&15];}return out;
}
