void emit(const std::filesystem::path& root, const std::string& name,
          Message& message) {
  if (message.get_payload().length() != 0 || message.get_data().length() != 0)
    throw std::runtime_error("encoder input must have empty front and data");
  // Direct dispatch invokes the actual native feature-selected payload encoder;
  // Message::encode's decoded-payload reuse path is deliberately not involved.
  message.encode_payload(features);
  if (message.get_header().version != (message.get_type() == 103 ? 1 : 2))
    throw std::runtime_error("native encoder did not select current map version");
  // Message::encode now only updates the native envelope and footer after
  // the direct fresh-object payload encode above. No decoded bytes are used.
  message.set_seq(1);  // Explicit offline transport input, not live session state.
  message.set_priority(CEPH_MSG_PRIO_DEFAULT);
  message.encode(features, MSG_CRC_ALL, true);
  const auto& header = message.get_header();
  const auto& footer = message.get_footer();
  if (header.front_len != message.get_payload().length() ||
      header.middle_len != message.get_middle().length() ||
      header.data_len != message.get_data().length())
    throw std::runtime_error("native envelope lengths disagree with payloads");
  // Project the fresh native envelope into the native v2 struct, as required
  // by its public MessageFrame API. This does not execute ProtocolV2's live
  // write_message/session path. ACK sequence 3 is another explicit test input.
  ceph_msg_header2 header2{};
  header2.seq = header.seq;
  header2.tid = header.tid;
  header2.type = header.type;
  header2.priority = header.priority;
  header2.version = header.version;
  header2.data_off = header.data_off;
  header2.ack_seq = 3;
  header2.flags = footer.flags;
  header2.compat_version = header.compat_version;
  header2.reserved = header.reserved;
  auto frame = ceph::msgr::v2::MessageFrame::Encode(
      header2, message.get_payload(), message.get_middle(), message.get_data());
  ceph::buffer::list encoded_header;
  encoded_header.append(reinterpret_cast<const char*>(&frame.header()),
                        sizeof(frame.header()));
  if (encoded_header.length() != 41)
    throw std::runtime_error("native v2 message header size changed");
  write_segment(root / (name + ".header.bin"), encoded_header);
  std::ofstream metadata(root / (name + ".native-header.json"));
  metadata.exceptions(std::ios::failbit | std::ios::badbit);
  metadata << "{\"type\":" << uint16_t(header.type)
           << ",\"version\":" << uint16_t(header.version)
           << ",\"compat\":" << uint16_t(header.compat_version)
           << ",\"tid\":" << uint64_t(header.tid)
           << ",\"seq\":" << uint64_t(header.seq)
           << ",\"priority\":" << uint16_t(header.priority)
           << ",\"front_len\":" << uint32_t(header.front_len)
           << ",\"middle_len\":" << uint32_t(header.middle_len)
           << ",\"data_len\":" << uint32_t(header.data_len)
           << ",\"data_off\":" << uint16_t(header.data_off)
           << ",\"flags\":" << unsigned(footer.flags)
           << ",\"ack_seq\":" << uint64_t(frame.header().ack_seq)
           << ",\"reserved\":" << uint16_t(header.reserved) << "}\n";
  write_segment(root / (name + ".front.bin"), message.get_payload());
  write_segment(root / (name + ".data.bin"), message.get_data());
  std::cout << name << "\t" << message.get_payload().length() << "\t"
            << message.get_data().length() << "\n";
}

void receipt(const std::filesystem::path& root,const std::string& name,int type,uint32_t epoch,const std::string& fsid,const std::string& encoded,size_t count){
 std::ofstream out(root/(name+".decoded-map.json"));out.exceptions(std::ios::failbit|std::ios::badbit);
 out << "{\"message_type\":" << type << ",\"epoch\":" << epoch << ",\"fsid_hex\":\"" << fsid
     << "\",\"encoded_map_hex\":\"" << hex(encoded) << "\",\"entry_count\":" << count << "}\n";
}
void emit_fs(const std::filesystem::path& root,const std::string& name,const uuid_d& fsid,bool populated){
 FSMapUser map;map.epoch=populated?17:0;map.legacy_client_fscid=populated?1:FS_CLUSTER_ID_NONE;
 if(populated){FSMapUser::fs_info_t first,second;first.cid=1;first.name="cephfs-a";second.cid=7;second.name=std::string("binary\0name",11);map.filesystems[1]=first;map.filesystems[7]=second;}
 auto source=ceph::make_message<MFSMapUser>(fsid,map);emit(root,name,*source);
 auto decoded=ceph::make_message<MFSMapUser>();decoded->set_header(source->get_header());ceph::buffer::list payload(source->get_payload());decoded->set_payload(payload);decoded->decode_payload();
 const auto& got=decoded->get_fsmap();
 if(decoded->get_epoch()!=map.epoch||got.get_epoch()!=map.epoch||got.legacy_client_fscid!=map.legacy_client_fscid||got.filesystems.size()!=map.filesystems.size())throw std::runtime_error("native FSMapUser identity decode");
 for(const auto& [id,info]:map.filesystems){auto p=got.filesystems.find(id);if(p==got.filesystems.end()||p->second.cid!=info.cid||p->second.name!=info.name)throw std::runtime_error("native FSMapUser entries decode");}
 receipt(root,name,103,got.epoch,"",decoded->get_payload().to_str().substr(4),got.filesystems.size());
}
void emit_mds(const std::filesystem::path& root,const std::string& name,const uuid_d& fsid,const MDSMap& map){
 auto source=ceph::make_message<MMDSMap>(fsid,map);emit(root,name,*source);
 auto decoded=ceph::make_message<MMDSMap>();decoded->set_header(source->get_header());ceph::buffer::list payload(source->get_payload());decoded->set_payload(payload);decoded->decode_payload();
 MDSMap got;got.decode(decoded->get_encoded());
 if(decoded->fsid!=fsid||decoded->get_epoch()!=map.get_epoch()||got.get_epoch()!=map.get_epoch()||got.get_flags()!=map.get_flags()||got.get_max_mds()!=map.get_max_mds()||got.get_fs_name()!=map.get_fs_name()||got.get_mds_info().size()!=map.get_mds_info().size()||got.get_required_client_features()!=map.get_required_client_features())throw std::runtime_error("native MDSMap identity/features decode");
 for(const auto& [id,info]:map.get_mds_info()){
  const auto& result=got.get_mds_info_gid(id);
  if(result.global_id!=info.global_id||result.name!=info.name||result.rank!=info.rank||result.inc!=info.inc||result.state!=info.state||result.state_seq!=info.state_seq||result.addrs!=info.addrs||result.laggy_since!=info.laggy_since||result.export_targets!=info.export_targets||result.mds_features!=info.mds_features||result.flags!=info.flags||result.join_fscid!=info.join_fscid)throw std::runtime_error("native MDSMap daemon decode");
 }
 receipt(root,name,21,got.get_epoch(),hex(std::string(decoded->fsid.bytes(),16)),decoded->get_encoded().to_str(),got.get_mds_info().size());
}
