int main(int argc,char** argv){try{
 if(argc!=2)throw std::runtime_error("usage: native-mds-map-encoder OUTPUT_DIR");const std::filesystem::path root(argv[1]);std::filesystem::create_directories(root);
 uuid_d fsid;if(!fsid.parse("00112233-4455-6677-8899-aabbccddeeff"))throw std::runtime_error("FSID parse");
 emit_fs(root,"mds-map-native-fsmap-empty",fsid,false);emit_fs(root,"mds-map-native-fsmap-multi",fsid,true);
 MDSMap empty;MapFixture populated(false),unknown(true);
 emit_mds(root,"mds-map-native-mdsmap-empty",fsid,empty);emit_mds(root,"mds-map-native-mdsmap-populated",fsid,populated);emit_mds(root,"mds-map-native-mdsmap-unknown",fsid,unknown);
 return 0;}catch(const std::exception& error){std::cerr<<error.what()<<"\n";return 1;}}
